// Map Google Form/Sheet columns to GHL contact fields
const row = $input.first().json;

const firstName = row['First Name'] || row['first_name'] || row['firstName'] || '';
const lastName = row['Last Name'] || row['last_name'] || row['lastName'] || '';
const email = (row['Email'] || row['email'] || row['Email Address'] || '').toString().trim().toLowerCase();
const rawPhone = String(row['Phone'] || row['phone'] || row['Phone Number'] || '');
const phone = rawPhone.replace(/[^\d+]/g, '');
const eventName = row['Event Name'] || row['event_name'] || row['Event'] || '';
const notes = row['Notes'] || row['notes'] || row['Comments'] || '';
const timestamp = row['Timestamp'] || row['timestamp'] || new Date().toISOString();

if (!email && !phone) {
  throw new Error('Lead must have at least an email or phone number');
}

return [{
  json: {
    firstName,
    lastName,
    email,
    phone,
    eventName,
    notes,
    timestamp,
    source: 'Google Form - Event Lead'
  }
}];

// Extract the contact ID from the upsert response
const response = $input.first().json;
const contactId = response.contact?.id || response.id;
const isNew = response.new !== undefined ? response.new : true;
const leadData = $('Map Lead Fields').first().json;

if (!contactId) {
  throw new Error('Failed to get contact ID from GHL response: ' + JSON.stringify(response));
}

return [{
  json: {
    contactId,
    isNewContact: isNew,
    firstName: leadData.firstName,
    lastName: leadData.lastName,
    email: leadData.email,
    eventName: leadData.eventName,
    source: leadData.source
  }
}];

const pipelinesResponse = $input.first().json;
const contactData = $('Extract Contact ID').first().json;

// Check if we got a valid pipelines response
const pipelines = pipelinesResponse.pipelines || [];
if (pipelines.length === 0) {
  throw new Error('No pipelines found. Your API token likely needs the "opportunities.write" and "opportunities.readonly" scopes. Go to GHL Settings > Integrations > your Private Integration > Scopes and enable them, then re-authorize.');
}

// Validate pipeline ID
const targetPipelineId = 'DEs336XJX4T8J1orIqYm';
const pipeline = pipelines.find(p => p.id === targetPipelineId);
if (!pipeline) {
  const available = pipelines.map(p => `${p.name} (${p.id})`).join(', ');
  throw new Error(`Pipeline ID "${targetPipelineId}" not found. Available pipelines: ${available}`);
}

// Validate stage ID
const targetStageId = 'ec805333-bd77-4346-bc77-844b7126ea9c';
const stages = pipeline.stages || [];
const stage = stages.find(s => s.id === targetStageId);
if (!stage) {
  const available = stages.map(s => `${s.name} (${s.id})`).join(', ');
  throw new Error(`Stage ID "${targetStageId}" not found in pipeline "${pipeline.name}". Available stages: ${available}`);
}

return [{
  json: {
    ...contactData,
    pipelineId: targetPipelineId,
    pipelineStageId: targetStageId,
    pipelineName: pipeline.name,
    stageName: stage.name
  }
}];

const opportunity = $input.first().json;
const contactData = $('Extract Contact ID').first().json;
const oppId = opportunity.opportunity?.id || opportunity.id || 'unknown';
const action = contactData.isNewContact ? 'Created new' : 'Updated existing';

console.log(`${action} GHL contact ${contactData.contactId} and opportunity ${oppId}`);

return [{
  json: {
    success: true,
    contactId: contactData.contactId,
    isNewContact: contactData.isNewContact,
    opportunityId: oppId,
    message: `${action} lead and added to pipeline: ${contactData.firstName} ${contactData.lastName}`
  }
}];

const error = $input.first().json;
const leadData = $('Map Lead Fields').first().json;
const leadName = `${leadData.firstName} ${leadData.lastName}`;
const errorDetail = error.message || error.body || JSON.stringify(error);

console.error(`Failed for ${leadName} (${leadData.email}): ${errorDetail}`);

return [{
  json: {
    success: false,
    error: errorDetail,
    leadEmail: leadData.email,
    leadName,
    message: `Failed to process lead: ${leadName}`
  }
}];
